const page = penpot.currentPage;
if (!page) throw new Error("No active Penpot page");
const root = page.root;
const children = Array.from(root.children || []);
const prior = children.find(s => s.name === "Doing CBT AR — Study Design System");
if (prior) return {ok:true, reused:true, boardName:prior.name};

let maxRight = 0;
for (const s of children) {
  const right = Number(s.x || 0) + Number(s.width || 0);
  if (Number.isFinite(right) && right > maxRight) maxRight = right;
}
const bx = maxRight + 240;
const by = 120;
const board = penpot.createBoard();
board.name = "Doing CBT AR — Study Design System";
board.resize(1200, 1600);
board.x = bx;
board.y = by;
board.fills = [{fillColor:"#F7F3EA", fillOpacity:1}];

const addRect = (name,x,y,w,h,color,r=20,stroke=null) => {
  const s = penpot.createRectangle();
  s.name = name;
  s.resize(w,h);
  s.x = bx+x; s.y = by+y;
  s.fills = [{fillColor:color, fillOpacity:1}];
  s.borderRadius = r;
  if (stroke) s.strokes = [{strokeColor:stroke, strokeOpacity:1, strokeWidth:1}];
  board.insertChild(board.children.length, s);
  return s;
};
const addText = (name,content,x,y,w,h,size,color,weight="400") => {
  const t = penpot.createText(content);
  if (!t) throw new Error("Text creation failed");
  t.name = name;
  t.fontSize = String(size);
  t.fontFamily = "Noto Sans Arabic";
  t.fontWeight = weight;
  t.fills = [{fillColor:color, fillOpacity:1}];
  t.x = bx+x; t.y = by+y;
  t.resize(w,h);
  t.growType = "fixed";
  board.insertChild(board.children.length, t);
  return t;
};

